function globMatch(text: string, pattern: string): boolean {
  const m = text.length, n = pattern.length;
  // below[j] = text[i+1:] matches pattern[j:]; starts as the empty-text row
  let below: boolean[] = new Array(n + 1).fill(false);
  below[n] = true;
  for (let j = n - 1; j >= 0; j--) below[j] = pattern[j] === "*" && below[j + 1];
  for (let i = m - 1; i >= 0; i--) {
    const cur: boolean[] = new Array(n + 1).fill(false);
    for (let j = n - 1; j >= 0; j--) {
      const p = pattern[j];
      if (p === "*") cur[j] = cur[j + 1] || below[j];
      else cur[j] = (p === "?" || p === text[i]) && below[j + 1];
    }
    below = cur;
  }
  return below[0];
}

