function globMatch(text: string, pattern: string): boolean {
  const m = text.length, n = pattern.length;
  let i = 0, j = 0, star = -1, mark = 0;
  while (i < m) {
    if (j < n && (pattern[j] === "?" || pattern[j] === text[i])) { i++; j++; }
    else if (j < n && pattern[j] === "*") { star = j; mark = i; j++; } // star starts empty
    else if (star !== -1) { j = star + 1; mark++; i = mark; }          // star eats one more
    else return false;
  }
  while (j < n && pattern[j] === "*") j++;
  return j === n;
}

